\label{d:ES-and-SES}
A category ${\sf C}$ is said to have the
\begin{enumerate}
\item[(\textnormal{ES})]\label{ES} \emph{ES property} if every epi in ${\sf C}$ is an extremal epi;
\item[(\textnormal{SES})]\label{SES} \emph{strong ES property} if every mono in~${\sf C}$ is a regular mono.
\end{enumerate}

Let $A$ be an object of a category ${\sf C}$. We say that $A$ is
\begin{enumerate}[label=(\roman*)]
\item \emph{saturated} if every monomorphism in ${\sf C}$ with domain $A$ is extremal (equivalently, if every epi-mono in ${\sf C}$ with domain $A$ is an isomorphism);
\item \emph{absolutely closed} if every monomorphism in ${\sf C}$ with domain $A$ is regular.
\end{enumerate}
We denote by ${\sf Sat}({\sf C})$ and ${\sf Abs}({\sf C})$ the full subcategories of ${\sf C}$ defined by the saturated objects and the absolutely closed objects, respectively.

\label{d:AP-SAP-IPA}
A category ${\sf C}$ is said to have
\begin{enumerate}
\item[(AP)]\label{AP} the \emph{amalgamation property} if any span of monomorphisms $\alpha,\beta$ can be completed to a commutative square as in eq.~\eqref{eq:generic-amalgam} with $\gamma, \delta$ monic;
\item[(SAP)]\label{SAP} the \emph{strong amalgamation property} if any span of monomorphisms $\alpha,\beta$ can be completed to a commutative square as in eq.~\eqref{eq:generic-amalgam}, with $\gamma, \delta$ monic, that is also a pullback square;
\item[(IPA)]\label{IPA} the \emph{intersection property of amalgamations} if any span of monomorphisms $\alpha,\beta$ that can be completed to a commutative square as in eq.~\eqref{eq:generic-amalgam}, with $\gamma, \delta$ monic, can also be completed to a pullback square of monomorphisms.
\end{enumerate}

\label{def:Beth-com}
Let ${\sf C}$ be an lfp category. If it exists, a \emph{Beth companion of ${\sf C}$} is a full and replete mono-reflective subcategory
\[\begin{tikzcd}[column sep=4em]
\mathcal{B}({\sf C}) \arrow[hookrightarrow]{r}[yshift=5pt]{\text{\tiny{$\bot$}}} & {\sf C} \arrow[bend right=70,xshift=2pt]{l}
\end{tikzcd}\]
satisfying the following conditions:
\begin{enumerate}[label=(\alph*)]
\item $\mathcal{B}({\sf C})$ is lfp and the inclusion functor $\mathcal{B}({\sf C})\hookrightarrow {\sf C}$ preserves directed colimits;
\item\label{i:ES-comp} $\mathcal{B}({\sf C})$ satisfies the \textnormal{ES}~property (equivalently, it is balanced).
\end{enumerate}

\label{rem:order-on-epi-ext}
It is not difficult to see that, for any two epi-extensions $m,n\in \operatorname{Ext_{p}}(A)$,
\begin{enumerate}[label=(\roman*)]
\item\label{i:preceq-unique-epi-mono} $m\preccurlyeq n$ if, and only if, there is a (necessarily unique) epi-mono $h$ such that $n=h\circ m$;
\item\label{i:sym-equi} $m\sim n$ if, and only if, there is a (necessarily unique) isomorphism $h$ such that $n=h\circ m$;
\item\label{i:unique-epi-mono-is-iso} if $m\sim n$, then the unique epi-mono $h$ satisfying $n=h\circ m$ is an isomorphism.
\end{enumerate}

\label{l:maximal-saturated}
Let ${m\colon A\rightarrowtail E}$ be an epi-extension of $A$. The following statements are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:codomain-saturated} $E$ is saturated;
\item\label{i:maximal-in-EExt} $m$ is maximal in $\operatorname{Ext_{p}}(A)$.
\end{enumerate}

\label{l:basic-props-mono-reflections}
Let ${\sf D}$ be a full mono-reflective subcategory of a category ${\sf C}$. The inclusion functor $R\colon{\sf D}\hookrightarrow{\sf C}$ preserves epis and reflects both extremal and regular monos,
and the reflector $L\colon {\sf C}\to{\sf D}$ is faithful.

\label{t:Beth-companion-unique} 
Let ${\sf C}$ be an lfp category. If it exists, the Beth companion of ${\sf C}$ is unique. Moreover, the following statements are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:has-Beth-comp} ${\sf C}$ admits a Beth companion;
\item\label{i:Beth-comp-is-Sigma} ${\sf Sat}({\sf C})$ is a Beth companion of ${\sf C}$;
\item\label{i:Sigma-axiomatisable} ${\sf Sat}({\sf C})$ is closed under limits and directed colimits in ${\sf C}$.
\end{enumerate}

\label{rmk:axiomatisability-Beth-comp}
Theorem~\ref{t:Beth-companion-unique} allows us to reduce the question of whether the Beth companion exists to an axiomatisability property of the class of saturated objects. This is akin to the concept of \emph{model companion} in model theory~\cite{Rob77}. Recall that a first-order theory has a model companion if its class of \emph{existentially closed} models is elementary (i.e., can be axiomatised in first-order logic). The conditions in item~\ref{i:Sigma-axiomatisable} of Theorem~\ref{t:Beth-companion-unique} can be regarded as axiomatisability properties of the class of saturated objects; in fact, by \cite[Corollary~2.4]{MP1987}, they imply that ${\sf Sat}({\sf C})$ is the class of models of a finitary essentially algebraic theory. Because lfp categories do not come with a distinguished forgetful functor to the category of sets, we use closure under limits and directed colimits in place of  syntactic axiomatisability.

Continuing the analogy with model companions, it has been known since the 1970s that commutative rings do not have a model companion (see e.g.\ \cite[Corollary~57]{Cherlin1976}), but reduced and (von Neumann) regular commutative rings share the same model companion \cite{LS1973}. As we will see in Section~\ref{s:examples}, similar results hold for the Beth companions of these classes of rings.

\label{t:strong-Beth-companion-unique}
Let ${\sf C}$ be an lfp category. If it exists, the strong Beth companion of~${\sf C}$ is unique. Moreover, the following statements are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:has-strong-Beth-comp} ${\sf C}$ admits a strong Beth companion;
\item\label{i:beth-comp-exists-and-sat-equal-abs} ${\sf C}$ admits a Beth companion and ${\sf Sat}({\sf C})={\sf Abs}({\sf C})$;
\item\label{i:abs-is-strong-beth-comp} ${\sf Abs}({\sf C})$ is a (strong) Beth companion of ${\sf C}$. 
\end{enumerate}

\label{d:EAP}
A category has
\begin{enumerate}
\item[(\textnormal{EAP})]\label{EAP} the \emph{epimorphism amalgamation property} if any span of arrows $\alpha,\beta$, with $\alpha$ and $\beta$ epi-monic, can be completed to a commutative square as displayed below, where $\gamma$ and $\delta$ are monic.
\[\begin{tikzcd}[cells={nodes={inner sep=2pt, outer sep=1pt}}]
\phantom{\cdot} \arrow{r}{\alpha} \arrow{d}[swap]{\beta} & \phantom{\cdot} \arrow[dashed]{d}{\delta} \\
\phantom{\cdot} \arrow[dashed]{r}{\gamma} & \phantom{\cdot}
\end{tikzcd}\]
\end{enumerate}

\label{l:equivalent-problems}
Let ${\sf C}$ be an lfp category satisfying \textnormal{EAP}.
The following statements are equivalent for any full mono-reflective subcategory ${\sf D} \hookrightarrow {\sf C}$:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:catt-balanced} ${\sf D}$ is balanced;
\item\label{i:inverts-epi-monos} the reflector ${\sf C}\to{\sf D}$ inverts all epi-monos.
\end{enumerate}

If $X\in {\mathcal{X}}^{\perp}$, and $m\colon X\to Y$ is an epi-mono in ${\sf C}$, then there is an arrow $r$ making the following diagram commute.
\[\begin{tikzcd}
X \arrow{d}[swap]{m} \arrow{r}{\mathrm{id}_{X}} & X \\
Y \arrow[dashed]{ur}[swap]{r}
\end{tikzcd}\]
It follows that $m$ is both a section and an epimorphism, hence an isomorphism. Thus, $X$ is saturated.

\label{t:Beth-companion-amalgam-orthogonal}
Let ${\sf C}$ be an lfp category satisfying \textnormal{EAP}.
The following statements are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:cat-has-Beth-comp-amal} ${\sf C}$ admits a Beth companion;
\item\label{i:ort-X-is-Beth-comp} ${\mathcal{X}}^{\perp}$ is a Beth companion of ${\sf C}$;
\item\label{i:ort-X-closed-dir-colim} ${\mathcal{X}}^{\perp}$ is closed under directed colimits in ${\sf C}$, and every object of ${\sf C}$ admits an extension with codomain in ${\mathcal{X}}^{\perp}$.
\end{enumerate}

\label{d:TEM}
A category has 
\begin{enumerate}
\item[(TEM)]\label{TEM} \emph{transferable epi-monos} if any span of arrows $\alpha,\beta$, with $\alpha$ epi-monic, can be completed to a commutative square as displayed below, where $\gamma$ is epi-monic.
\[\begin{tikzcd}[cells={nodes={inner sep=2pt, outer sep=1pt}}]
\phantom{\cdot} \arrow{r}{\alpha} \arrow{d}[swap]{\beta} & \phantom{\cdot} \arrow[dashed]{d}{\delta} \\
\phantom{\cdot} \arrow[dashed]{r}[rightarrowtail]{\gamma} & \phantom{\cdot}
\end{tikzcd}\]
\end{enumerate}

\label{l:ort-vs-sat}
The following statements are equivalent for any lfp category ${\sf C}$:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:X-local-extension} every object of ${\sf C}$ admits an extension with codomain in ${\mathcal{X}}^{\perp}$;
\item\label{i:sat-and-ort-coincide} ${\sf Sat}({\sf C})={\mathcal{X}}^{\perp}$;
\item\label{i:transferable-epi-monos} ${\sf C}$ has transferable epi-monos.
\end{enumerate}

\label{l:X-ort-dir-colim-fp-domains}
Let ${\sf C}$ be an lfp category satisfying \textnormal{TEM}. The following are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:ort-X-closed-dir-col} ${\mathcal{X}}^{\perp}$ is closed under directed colimits in ${\sf C}$;
\item\label{i:saturation-epimonos-fp-domains} ${\mathcal{X}}^{\perp}=\mathcal{X}^{\perp}_{\mathrm{fpd}}$, where $\mathcal{X}_{\mathrm{fpd}}$ is the class of epi-monos in ${\sf C}$ with finitely presentable domains.
\end{enumerate}

\label{cor:Beth-TEM-omega-ort}
Let ${\sf C}$ be an lfp category with transferable epi-monos. The following statements are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:TEM-has-BC} ${\sf C}$ admits a Beth companion;
\item\label{i:TEM-Sat-dir-col} ${\sf Sat}({\sf C})$ ($={\mathcal{X}}^{\perp}$) is closed under directed colimits in ${\sf C}$;
\item\label{i:TEM-Sat-inj-class} ${\sf Sat}({\sf C})$ ($={\mathcal{X}}^{\perp}$) is an $\omega$-injectivity class in ${\sf C}$. 
\end{enumerate}

\label{r:TM}
Recall that a category ${\sf D}$ has
\begin{enumerate}
\item[(TM)]\label{TM} \emph{transferable monomorphisms} if any span $\alpha,\beta$, with $\alpha$ monic, can be completed to a commutative square as in eq.~\eqref{eq:generic-amalgam} with $\gamma$ monic.
\end{enumerate}
If ${\sf D}$ admits pushouts of monomorphisms along any morphism, then it has TM if, and only if, monomorphisms are stable under pushouts along any morphism. As in the proof of Proposition~\ref{p:transfer-AP}, an application of \cite[Lemma~1]{Ringel1971} shows that if ${\sf C}$ satisfies \textnormal{TM}~(and, a fortiori, \textnormal{AP}), then so does its Beth companion.

\label{thm:orthinverter}
Let ${\sf C}$ be an lfp category satisfying \textnormal{TEM}, and suppose the monad~$\mathbb{T}_{\mathcal{X}}$ is strongly finitary. 
The following statements are equivalent:
\begin{enumerate}[label=(\arabic*)]
\item\label{i:TEM-strongly-fin-has-BC} ${\sf C}$ admits a Beth companion;
\item\label{i:TEM-set-of-fp-epimonos} there exists a set $\mathcal{H}$ of epi-monos between finitely presentable objects of ${\sf C}$ such that ${\mathcal{H}}^{\perp}={\mathcal{X}}^{\perp}$;
\item\label{i:AP-Sat-ort-class} ${\mathcal{X}}^{\perp}$ is an $\omega$-orthogonality class in ${\sf C}$. 
\end{enumerate}

We define the following $2$-categories:
\begin{itemize}
\item ${\sf Lfp}$ has lfp categories as objects, lfp morphisms (see Section~\ref{s:lfp}) as arrows, and natural transformations between lfp morphisms as $2$-cells.
\item ${\sf Lex}$ has small categories with finite limits as objects, functors that preserve finite limits as arrows, and natural transformations between such functors as $2$-cells.
\end{itemize}

\label{t:GU-duality}
There exists a biequivalence of $2$-categories  
\[{\sf Lex}(-,{\sf Set})\colon {\sf Lex}^{{\mathrm{op}}} \leftrightarrows {\sf Lfp}  
